<script setup lang="ts">import { computed, ref } from 'vue';import { api } from '../api';import type { Plan,Estimate } from '../types';const props=defineProps<{plans:Plan[]}>();const planId=ref(props.plans[0]?.id??1);const billed=ref(1200);const used=ref(0);const result=ref<Estimate|null>(null);const error=ref('');const busy=ref(false);const money=(n:number)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);const chosen=computed(()=>props.plans.find(p=>p.id===planId.value));async function calculate(){error.value='';result.value=null;busy.value=true;try{result.value=await api.estimate({plan_id:planId.value,billed_amount:billed.value,deductible_used:used.value});}catch(e){error.value=e instanceof Error?e.message:'Could not calculate estimate';}finally{busy.value=false;}}</script>
<template><section class="estimate-panel"><div><span class="eyebrow">COST ESTIMATOR</span><h2>What might I pay?</h2><p class="muted">Adjust the service cost and your deductible progress to estimate your share.</p></div><div class="estimate-fields"><label>Insurance plan<select v-model.number="planId"><option v-for="p in plans" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Expected medical bill ($)<input v-model.number="billed" type="number" min="1" /></label><label>Deductible already paid ($)<input v-model.number="used" type="number" min="0" /></label><button class="primary-button" :disabled="busy || !chosen" @click="calculate">{{busy?'Calculating…':'Calculate my cost'}}</button></div><p v-if="error" class="error">{{error}}</p><div v-if="result" class="estimate-result"><div><span>Estimated you pay</span><strong>{{money(result.estimated_member_cost)}}</strong></div><div><span>Estimated plan pays</span><strong>{{money(result.estimated_plan_payment)}}</strong></div><small>Illustrative estimate based on the selected plan's simplified rules.</small></div></section></template>
